// src/NotificacionesPage.js
import React, { useEffect, useState, useMemo } from "react";
import { Link } from "react-router-dom";
import api from "./api/apiClient";
import logo from "./assets/logo-cancha.png";

// === helpers de formato ===
function formatearFecha(fechaStr) {
  if (!fechaStr) return "-";
  const d = new Date(fechaStr);
  if (Number.isNaN(d.getTime())) return "-";
  try {
    return d.toLocaleString("es-ES", {
      dateStyle: "medium",
      timeStyle: "short",
    });
  } catch {
    return d.toISOString().slice(0, 16).replace("T", " ");
  }
}

function normalizarLista(data) {
  if (!data) return [];

  // DEBUG: mira en la consola del navegador qué está llegando
  console.log("DEBUG notificaciones - raw data:", data);

  let lista = [];

  // Soporta varios formatos de respuesta
  if (Array.isArray(data.notificaciones)) {
    lista = data.notificaciones;
  } else if (Array.isArray(data.notifications)) {
    lista = data.notifications;
  } else if (Array.isArray(data.results)) {
    lista = data.results;
  } else if (Array.isArray(data.data)) {
    lista = data.data;
  } else if (Array.isArray(data)) {
    lista = data;
  }

  return lista.map((n) => {
    const tipo =
      n.tipo ||
      n.category ||
      n.tipo_notificacion ||
      n.evento ||
      "general";

    const titulo =
      n.titulo ||
      n.title ||
      (tipo === "reserva_confirmada"
        ? "Reserva Confirmada"
        : tipo === "reserva_cancelada"
        ? "Reserva Cancelada"
        : tipo === "recordatorio_reserva"
        ? "Recordatorio de Reserva"
        : "Notificación");

    const mensaje =
      n.mensaje || n.descripcion || n.detalle || n.message || "";

    const fecha =
      n.fecha ||
      n.created_at ||
      n.fecha_creacion ||
      n.fecha_envio ||
      null;

    const leida =
      n.leida ??
      n.leido ??
      n.is_read ??
      n.vista ??
      false;

    return {
      id: n.id,
      tipo,
      titulo,
      mensaje,
      fecha,
      leida,
      raw: n,
    };
  });
}

function configTipo(tipo) {
  switch (tipo) {
    case "reserva_confirmada":
      return {
        icono: "✅",
        badgeText: "Reserva confirmada",
        badgeClasses:
          "bg-emerald-50 text-emerald-700 border border-emerald-200",
      };
    case "reserva_cancelada":
    case "cancelacion":
      return {
        icono: "⚠️",
        badgeText: "Reserva cancelada",
        badgeClasses:
          "bg-red-50 text-red-600 border border-red-200",
      };
    case "recordatorio_reserva":
      return {
        icono: "⏰",
        badgeText: "Recordatorio",
        badgeClasses:
          "bg-amber-50 text-amber-700 border border-amber-200",
      };
    case "promocion":
      return {
        icono: "🎁",
        badgeText: "Promoción",
        badgeClasses:
          "bg-purple-50 text-purple-700 border border-purple-200",
      };
    default:
      return {
        icono: "🔔",
        badgeText: "Notificación",
        badgeClasses: "bg-slate-50 text-slate-700 border border-slate-200",
      };
  }
}

export default function NotificacionesPage() {
  const [notificaciones, setNotificaciones] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState(null);
  const [marcandoId, setMarcandoId] = useState(null);

  useEffect(() => {
    const fetchNotificaciones = async () => {
      setLoading(true);
      setErrorMsg(null);

      // Posibles endpoints de notificaciones (el primero que responda 200 se usa)
      const posiblesRutas = [
        "/api/notificaciones/",
        "/api/reservas/notificaciones/",
        "/api/deportistas/notificaciones/",
      ];

      let cargadas = [];
      let ultimoError = null;

      for (const ruta of posiblesRutas) {
        try {
          const res = await api.get(ruta);
          const data = res.data || {};
          const listaNormalizada = normalizarLista(data);

          listaNormalizada.sort((a, b) => {
            if (a.leida !== b.leida) return a.leida ? 1 : -1;
            const fa = a.fecha || "";
            const fb = b.fecha || "";
            return fb.localeCompare(fa);
          });

          cargadas = listaNormalizada;
          console.log("DEBUG notificaciones - usando endpoint:", ruta);
          break; // salimos del loop si este endpoint funcionó
        } catch (error) {
          ultimoError = error;
          const status = error.response?.status;
          console.warn("Error en endpoint de notificaciones", ruta, status);
          // si es 404 probamos la siguiente ruta, si es otro error lo recordamos
          continue;
        }
      }

      if (cargadas.length > 0) {
        setNotificaciones(cargadas);
        setErrorMsg(null);
      } else {
        // si no se pudo cargar nada:
        if (ultimoError && ultimoError.response && ultimoError.response.status !== 404) {
          setErrorMsg("Ocurrió un error al cargar tus notificaciones.");
        } else {
          // sin error crítico: simplemente no hay notificaciones
          setErrorMsg(null);
          setNotificaciones([]);
        }
      }

      setLoading(false);
    };

    fetchNotificaciones();
  }, []);

  const hayNoLeidas = useMemo(
    () => notificaciones.some((n) => !n.leida),
    [notificaciones]
  );

  // === marcar como leída ===
  const marcarComoLeida = async (notif) => {
    if (!notif || notif.leida) return;
    const id = notif.id;
    if (!id) return;

    setMarcandoId(id);

    try {
      // 1) Intentar endpoint específico /marcar-leida/
      try {
        await api.post(`/api/notificaciones/${id}/marcar-leida/`);
      } catch (error) {
        if (error.response && error.response.status === 404) {
          // 2) Si no existe, probar PATCH directamente
          await api.patch(`/api/notificaciones/${id}/`, {
            leida: true,
          });
        } else {
          throw error;
        }
      }

      // Actualizar estado local
      setNotificaciones((prev) =>
        prev.map((n) =>
          n.id === id ? { ...n, leida: true } : n
        )
      );
    } catch (error) {
      console.error("Error marcando notificación como leída", error);
      // no mostramos alert para no ser invasivos
    } finally {
      setMarcandoId(null);
    }
  };

  // === render ===
  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col">
        {/* Navbar */}
        <header className="bg-white border-b border-slate-200">
          <div className="max-w-6xl mx-auto flex items-center justify-between px-8 py-4">
            <div className="flex items-center gap-2">
              <img src={logo} alt="CanchaYa logo" className="w-7 h-7" />
              <span className="font-bold text-xl text-blue-700">
                CanchaYa
              </span>
            </div>
          </div>
        </header>

        <main className="flex-1 flex items-center justify-center">
          <p className="text-sm text-slate-500">
            Cargando tus notificaciones...
          </p>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* NAVBAR PERFIL DEPORTISTA */}
      <header className="bg-white border-b border-slate-200">
        <div className="max-w-6xl mx-auto flex items-center justify-between px-8 py-4">
          <div className="flex items-center gap-2">
            <img src={logo} alt="CanchaYa logo" className="w-7 h-7" />
            <span className="font-bold text-xl text-blue-700">
              CanchaYa
            </span>
          </div>

          <nav className="flex items-center gap-6 text-sm">
            <Link to="/deportista/buscar" className="text-slate-700">
              Buscar
            </Link>
            <Link
              to="/deportista/reservas"
              className="text-slate-700"
            >
              Mis Reservas
            </Link>
            <span className="px-4 py-2 rounded-full bg-slate-900 text-white font-semibold text-sm">
              Notificaciones
            </span>
            <Link to="/deportista/perfil" className="text-slate-700">
              Perfil
            </Link>

            <Link
              to="/login"
              className="ml-4 inline-flex items-center gap-2 px-4 py-2 rounded-xl border border-slate-200 text-sm font-semibold text-slate-800 bg-white hover:bg-slate-50"
            >
              <span>↪</span>
              <span>Cerrar Sesión</span>
            </Link>
          </nav>
        </div>
      </header>

      {/* CONTENIDO */}
      <main className="flex-1">
        <section className="max-w-5xl mx-auto px-8 py-8">
          <div className="flex items-center justify-between mb-2">
            <h1 className="text-xl font-semibold text-slate-900">
              Notificaciones
            </h1>
            {hayNoLeidas && (
              <span className="text-[11px] px-2 py-1 rounded-full bg-blue-50 text-blue-700 border border-blue-100">
                Tienes notificaciones sin leer
              </span>
            )}
          </div>
          <p className="text-sm text-slate-500 mb-6">
            Mantente al día con tus reservas y promociones.
          </p>

          {errorMsg && (
            <p className="mb-4 text-xs text-red-600">{errorMsg}</p>
          )}

          {notificaciones.length === 0 ? (
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 text-sm text-slate-500">
              Aún no tienes notificaciones. Cuando reserves o
              canceles una cancha, verás los avisos aquí.
            </div>
          ) : (
            <div className="space-y-3">
              {notificaciones.map((n) => {
                const cfg = configTipo(n.tipo);
                const esNoLeida = !n.leida;
                return (
                  <button
                    type="button"
                    key={n.id}
                    onClick={() => marcarComoLeida(n)}
                    className={
                      "w-full text-left rounded-2xl border shadow-sm px-5 py-4 flex items-start gap-3 transition " +
                      (esNoLeida
                        ? "bg-blue-50/70 border-blue-100 hover:bg-blue-50"
                        : "bg-white border-slate-200 hover:bg-slate-50")
                    }
                    disabled={marcandoId === n.id}
                  >
                    {/* icono */}
                    <div className="mt-1">
                      <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-lg">
                        {cfg.icono}
                      </div>
                    </div>

                    {/* contenido */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <h2 className="text-sm font-semibold text-slate-900 truncate">
                            {n.titulo}
                          </h2>
                          <p className="text-xs text-slate-600 mt-1 line-clamp-2">
                            {n.mensaje}
                          </p>
                        </div>
                        {/* punto azul de no leída */}
                        <div className="flex flex-col items-end gap-1">
                          <span
                            className={
                              "px-2 py-0.5 rounded-full text-[10px] font-semibold " +
                              cfg.badgeClasses
                            }
                          >
                            {cfg.badgeText}
                          </span>
                          {esNoLeida && (
                            <span className="w-2 h-2 rounded-full bg-blue-500" />
                          )}
                        </div>
                      </div>

                      <p className="mt-2 text-[11px] text-slate-500">
                        {formatearFecha(n.fecha)}
                        {marcandoId === n.id && " · Marcando como leída..."}
                      </p>
                    </div>
                  </button>
                );
              })}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
